sys.path.insert(0,'/app/output');from kinematics import *;from perception import scene
q=np.array(json.load(open('/app/output/latest/meta.json'))['proprio']['now'][6:13]);base=np.array([.4,.1,0.])
for xyz in [[1.025,.13,.6],[1.025,.13,.412],[1.1,.25,.6],[1.1,.25,.46]]:
