  try:
   qq=ik(np.array(xyz),look_rotation(90,yaw),q,base);print(xyz,'yaw',yaw,qq.round(3));
  except ValueError as e:print(xyz,'yaw',yaw,str(e)[:60])
rgb,d,P=scene();r,g,b=rgb.astype(float).transpose(2,0,1)
masks={'red':(r>g*1.8)&(r>b*1.8)&(r>35),'green':(g>r*1.8)&(g>b*1.8)&(g>35),'blue':(b>r*1.8)&(b>g*1.8)&(b>35),'yellow':(r>b*2)&(g>b*2)&(r>70)&(g>60)}
