  ps=P[M & (abs(P[:,:,2]-z)<.0006)]
  lo,hi=np.quantile(ps,[.01,.99],axis=0)
  t[name][kind]=((lo+hi)/2).tolist()
  print(name,kind,len(ps),'bounds',lo.round(5),hi.round(5),'center',np.round(t[name][kind],5))
json.dump(t,open('/app/output/targets.json','w'),indent=2)
